import React, { useState } from "react";
import { FontAwesomeIcon } from "@fortawesome/react-fontawesome";
import { faTrash, faGripVertical } from "@fortawesome/free-solid-svg-icons";
import { DragDropContext, Droppable, Draggable } from "@hello-pangea/dnd";
import "./storelist.css";

interface Store {
  id: string | number;
  seq: number;
  label: string;
  city: string;
  state: string;
}

interface StoreListProps {
  data: Store[];
}

const StoreList: React.FC<StoreListProps> = ({ data }) => {
  //state to manage the list of stores
  const [storeList, setStoreList] = useState<Store[]>(data);

  const handleDelete = (id: string | number) => {
    const updatedList = storeList.filter(
      (store) => store.id.toString() !== id.toString()
    );
    setStoreList(updatedList);
  };

  const handleAddStore = () => {
    const newStore: Store = {
      id: storeList.length + 1,
      seq: storeList.length + 1,
      label: "New Store",
      city: "New City",
      state: "NC",
    };
    setStoreList([...storeList, newStore]);
  };

  const handleDragEnd = (result: any) => {
    if (!result.destination) return;

    const items = [...storeList];
    const [reorderedItem] = items.splice(result.source.index, 1);
    items.splice(result.destination.index, 0, reorderedItem);
    setStoreList(items);
  };

  return (
    <div className="store-container">
      <DragDropContext onDragEnd={handleDragEnd}>
        <Droppable droppableId="stores">
          {(provided) => (
            <table>
              <thead>
                <tr>
                  <th></th>
                  <th> |</th>
                  <th>S.No</th>
                  <th>Store</th>
                  <th>City</th>
                  <th>State</th>
                </tr>
              </thead>
              <tbody ref={provided.innerRef} {...provided.droppableProps}>
                {storeList.map((store, index) => (
                  <Draggable
                    key={store.id.toString()}
                    draggableId={store.id.toString()}
                    index={index}
                  >
                    {(provided) => (
                      <tr
                        ref={provided.innerRef}
                        {...provided.draggableProps}
                        {...provided.dragHandleProps}
                      >
                        <td>
                          <FontAwesomeIcon
                            icon={faTrash}
                            onClick={() => handleDelete(store.id)}
                            style={{ cursor: "pointer", color: "red" }}
                          />
                        </td>
                        <td>
                          <FontAwesomeIcon
                            icon={faGripVertical}
                            style={{ cursor: "grab" }}
                          />
                        </td>
                        <td>{store.seq}</td>
                        <td>{store.label}</td>
                        <td>{store.city}</td>
                        <td>{store.state}</td>
                      </tr>
                    )}
                  </Draggable>
                ))}
                {provided.placeholder}
              </tbody>
            </table>
          )}
        </Droppable>
      </DragDropContext>

      <div className="new-store-btn-container">
        <button className="add-store-btn" onClick={handleAddStore}>
          NEW STORE
        </button>
      </div>
    </div>
  );
};

export default StoreList;
